                    } if (vid.msRequestFullscreen) { // IE/Edge
                        vid.msRequestFullscreen();
                    }
                });
            }
        }
        catch (e) {
            console.error(e)
        }
        finally {
            return { id, preview, previewWindow };
        }

    }
